-- 检查云游是否可用，该接口为异步返回
-- @param cb, function类型，检查结果回调。该cb的返回参数如下：
--        @param succ，bool类型，表示该检查操作是否成功
--        @param ... ,可变参数类型，与succ有关。取值如下：
--          succ为true, 则可变参数为is_available，表示当前云游是否可用
--          succ为false，则可变参数为2个，错误码和错误信息
function M.check_cloud_game_available(cb)
    CSG.check_cloud_available(function(succ, ...)
        if succ then
            local available = ...
            E.LOG.debug(TAG, "check_cloud_game_available succ, available:" .. tostring(available))
        else
