-- 退出云游接口
-- @param is_force: bool类型，true: 强制退出，此时云游立即关闭，false: 云游内部会弹窗询问玩家是否退出，玩家根据需要可以继续游戏
-- @param params: table类型，包含参数如下：
--      @param content: 字符串，提示给玩家的退出弹窗显示内容
function M.exit_cloud_game(is_force, params, cb)
    -- 如果是selfStart，则 退出云游 退出APP，如果非selfStart，则pause 。交给cloud_state_manager处理
    params = params or {}
    local isRationale = not is_force
    params[CSG.CONNECT_PARAMS.SHOW_RATIONALE] = isRationale
    M.close_cloud_game_view(params, function(succ, ...)
        E.LOG.debug(TAG, "exit_cloud_game result:" .. tostring(succ))
        if cb then
            cb(succ, ...)
        end
    end)
end

